<script setup lang="ts">
import {computed,useId} from 'vue'
import type {AuthorValue,PlotCheck} from './types'
const props=defineProps<{check:PlotCheck;value:AuthorValue;transitions?:{id:string;title:string}[];ending?:boolean}>()
const listId=useId()
const people=computed(()=>props.value.definition.entities.filter(e=>e.type==='character')),places=computed(()=>props.value.definition.entities.filter(e=>e.type==='place')),items=computed(()=>props.value.definition.entities.filter(e=>e.type==='item'))
function valueType(event:Event){const kind=(event.target as HTMLSelectElement).value;props.check.value=kind==='number'?0:kind==='boolean'?true:''}
</script>
<template><div class="plot-check-editor"><label>验收依据<select v-model="check.kind"><option value="field">状态值等于</option><option value="knowledge">人物知道线索</option><template v-if="!ending"><option value="visit">曾抵达地点</option><option value="location">当前位于地点</option><option value="inventory">当前持有物品</option><option value="acquired">曾获得物品</option><option value="transfer">实际交给指定人物</option><option v-if="transitions?.length" value="transition">办理回执已确认</option></template></select></label><label>验收人物<select v-model="check.entityId"><option value="player">当前玩家</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label v-if="['visit','location'].includes(check.kind)">地点<select v-model="check.placeId"><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}}</option></select></label><template v-if="['inventory','acquired','transfer'].includes(check.kind)"><label>物品<select v-model="check.itemId"><option v-for="p in items" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>数量<input v-model.number="check.quantity" type="number" min="1" max="100000"></label></template><label v-if="check.kind==='transfer'">实际接收者<select v-model="check.toId"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label v-if="check.kind==='knowledge'">线索<select v-model="check.loreId"><option v-for="p in value.definition.lore" :key="p.id" :value="p.id">{{p.title}}</option></select></label><label v-if="check.kind==='transition'">办理操作<select v-model="check.value"><option v-for="t in transitions" :key="t.id" :value="t.id">{{t.title}}</option></select></label><template v-if="check.kind==='field'"><label>状态字段<input v-model="check.field" :list="listId" placeholder="如 author_decision"></label><datalist :id="listId"><option v-for="f in value.statusFields" :key="f.id" :value="f.id">{{f.label}}</option></datalist><label>比较值类型<select :value="typeof check.value" @change="valueType"><option value="string">文字</option><option value="number">数字</option><option value="boolean">是／否</option></select></label><label>满足时的值<input v-if="typeof check.value==='number'" v-model.number="check.value" type="number"><select v-else-if="typeof check.value==='boolean'" v-model="check.value"><option :value="true">是</option><option :value="false">否</option></select><input v-else v-model="check.value" maxlength="200"></label></template></div></template>
<style scoped>.plot-check-editor{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr));gap:12px;padding:12px;border:1px solid var(--border,#e8e1d8);border-radius:10px;margin:12px 0}.plot-check-editor label{min-width:0;margin:0}.plot-check-editor input,.plot-check-editor select{width:100%;min-height:44px}</style>
